String yamlText = """
    aplikacja: JavaQuest
    port: 8080
    funkcje:
      - logowanie
      - raportowanie
    baza-danych:
      host: localhost
      port: 5432
    """;

Yaml yaml = new Yaml();
Map<String, Object> dane = yaml.load(yamlText);
List<String> funkcje = (List<String>) dane.get("funkcje");
Map<String, Object> baza = (Map<String, Object>) dane.get("baza-danych");

Map<String, Object> serwer = new LinkedHashMap<>();
serwer.put("nazwa", "JavaQuest");
String dump = yaml.dump(serwer);

String wieleDokumentow = "---\nnazwa: A\n---\nnazwa: B\n";
for (Object doc : yaml.loadAll(wieleDokumentow)) {
    System.out.println(doc);
}

